@@ -0,0 +1,11 @@
+# launcher（LVGL 演示）
+
+队伍 349 FedoraVForce 的 LVGL 触控演示应用，映射到 openvela
+`packages/demos/contest2026_349_launcher`。
+
+- 锁屏页：运行时钟，上滑/点击圆形手柄解锁
+- 桌面页：时钟、heap/FPS 状态、About / Paint 两个入口
+- About 页：S6 移植信息（GICv3、MIPI DSI、GT9XX）与实时 heap/FPS
+- Paint 页：全屏手写画板，四色画笔 + Clear
+
+运行：NSH 下执行 `launcher`。
diff --git a/app/launcher/launcher_main.c b/app/launcher/launcher_main.c
new file mode 100644
index 0000000..4f620e1
--- /dev/null
+++ b/app/launcher/launcher_main.c
@@ -0,0 +1,609 @@
+/****************************************************************************
+ * Contest 2026 team 349 (FedoraVForce) - LVGL launcher demo
+ * VSAI LogicPi A1 (Amlogic S6): MIPI DSI 1080x1920 + GT9XX touch
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#include <malloc.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <time.h>
+#include <unistd.h>
+
+#include <lvgl/lvgl.h>
+
+#define LAUNCHER_SCREEN_W     1080
+#define LAUNCHER_SCREEN_H     1920
+
+#define LAUNCHER_BG_COLOR     0x0e1821
+#define LAUNCHER_CARD_COLOR   0x17262f
+#define LAUNCHER_ACCENT       0x00a8f3
+#define LAUNCHER_TEXT_DIM     0x8fb0bf
+
+#define UNLOCK_DRAG_DIST      240
+#define CANVAS_BUF_SIZE       (LAUNCHER_SCREEN_W * LAUNCHER_SCREEN_H * 2)
+#define TOUCH_DEVPATH         "/dev/input0"
+
+/****************************************************************************
+ * Private Data
+ ****************************************************************************/
+
+static lv_obj_t *g_lock_scr;
+static lv_obj_t *g_home_scr;
+static lv_obj_t *g_about_scr;
+static lv_obj_t *g_paint_scr;
+
+static lv_obj_t *g_lock_clock;
+static lv_obj_t *g_home_clock;
+static lv_obj_t *g_home_uptime;
+static lv_obj_t *g_about_heap;
+static lv_obj_t *g_about_fps;
+static lv_obj_t *g_home_fps;
+
+static lv_obj_t *g_canvas;
+static lv_color_t *g_canvas_buf;
+static lv_color_t g_brush_color;
+static bool g_brush_down;
+static lv_point_t g_brush_prev;
+static lv_point_t g_drag_start;
+
+static const uint32_t g_palette[] =
+{
+  0x000000, 0xe8443a, 0x00a8f3, 0x27c24a
+};
+
+static volatile uint32_t g_refr_count;
+static uint32_t g_fps;
+
+/****************************************************************************
+ * Private Functions
+ ****************************************************************************/
+
+static uint32_t launcher_uptime_sec(void)
+{
+  struct timespec ts;
+
+  clock_gettime(CLOCK_MONOTONIC, &ts);
+  return (uint32_t)ts.tv_sec;
+}
+
+static void launcher_format_clock(char *buf, size_t buflen)
+{
+  uint32_t sec = launcher_uptime_sec();
+
+  snprintf(buf, buflen, "%02u:%02u:%02u",
+           (sec / 3600) % 100, (sec / 60) % 60, sec % 60);
+}
+
+static void launcher_switch_scr(lv_obj_t *scr, lv_screen_load_anim_t anim)
+{
+  lv_screen_load_anim(scr, anim, 250, 0, false);
+}
+
+static void launcher_refr_event_cb(lv_event_t *e)
+{
+  UNUSED(e);
+  g_refr_count++;
+}
+
+/****************************************************************************
+ * Name: lock screen
+ ****************************************************************************/
+
+static void launcher_unlock(void)
+{
+  launcher_switch_scr(g_home_scr, LV_SCR_LOAD_ANIM_MOVE_TOP);
+}
+
+static void launcher_lock_handle_event_cb(lv_event_t *e)
+{
+  lv_event_code_t code = lv_event_get_code(e);
+  lv_indev_t *indev = lv_indev_active();
+  lv_point_t p;
+
+  if (indev == NULL)
+    {
+      return;
+    }
+
+  lv_indev_get_point(indev, &p);
+
+  if (code == LV_EVENT_PRESSED)
+    {
+      g_drag_start = p;
+    }
+  else if (code == LV_EVENT_PRESSING)
+    {
+      if (g_drag_start.y - p.y > UNLOCK_DRAG_DIST)
+        {
+          launcher_unlock();
+        }
+    }
+  else if (code == LV_EVENT_SHORT_CLICKED)
+    {
+      launcher_unlock();
+    }
+}
+
+static void launcher_create_lock_scr(void)
+{
+  lv_obj_t *scr = lv_obj_create(NULL);
+  lv_obj_t *obj;
+
+  lv_obj_set_style_bg_color(scr, lv_color_hex(LAUNCHER_BG_COLOR), 0);
+
+  g_lock_clock = lv_label_create(scr);
+  lv_obj_set_style_text_font(g_lock_clock, &lv_font_montserrat_48, 0);
+  lv_obj_set_style_text_color(g_lock_clock, lv_color_hex(0xffffff), 0);
+  lv_label_set_text(g_lock_clock, "00:00:00");
+  lv_obj_align(g_lock_clock, LV_ALIGN_CENTER, 0, -260);
+
+  obj = lv_label_create(scr);
+  lv_obj_set_style_text_font(obj, &lv_font_montserrat_24, 0);
+  lv_obj_set_style_text_color(obj, lv_color_hex(LAUNCHER_TEXT_DIM), 0);
+  lv_label_set_text(obj, "openvela on LogicPi A1");
+  lv_obj_align(obj, LV_ALIGN_CENTER, 0, -160);
+
+  obj = lv_obj_create(scr);
+  lv_obj_set_size(obj, 180, 180);
+  lv_obj_set_style_radius(obj, LV_RADIUS_CIRCLE, 0);
+  lv_obj_set_style_bg_color(obj, lv_color_hex(LAUNCHER_ACCENT), 0);
+  lv_obj_set_style_border_width(obj, 0, 0);
+  lv_obj_set_scrollbar_mode(obj, LV_SCROLLBAR_MODE_OFF);
+  lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
+  lv_obj_align(obj, LV_ALIGN_BOTTOM_MID, 0, -300);
+  lv_obj_add_event_cb(obj, launcher_lock_handle_event_cb, LV_EVENT_ALL,
+                      NULL);
+
+  {
+    lv_obj_t *sym = lv_label_create(obj);
+
+    lv_obj_set_style_text_font(sym, &lv_font_montserrat_48, 0);
+    lv_obj_set_style_text_color(sym, lv_color_hex(LAUNCHER_BG_COLOR), 0);
+    lv_label_set_text(sym, LV_SYMBOL_UP);
+    lv_obj_center(sym);
+  }
+
+  obj = lv_label_create(scr);
+  lv_obj_set_style_text_font(obj, &lv_font_montserrat_16, 0);
+  lv_obj_set_style_text_color(obj, lv_color_hex(LAUNCHER_TEXT_DIM), 0);
+  lv_label_set_text(obj, "Swipe up or tap to unlock");
+  lv_obj_align(obj, LV_ALIGN_BOTTOM_MID, 0, -100);
+
+  g_lock_scr = scr;
+}
+
+/****************************************************************************
+ * Name: about screen
+ ****************************************************************************/
+
+static void launcher_back_event_cb(lv_event_t *e)
+{
+  UNUSED(e);
+  launcher_switch_scr(g_home_scr, LV_SCR_LOAD_ANIM_MOVE_BOTTOM);
+}
+
+static void launcher_about_info_line(lv_obj_t *parent, const char *key,
+                                     const char *val, int32_t y)
+{
+  lv_obj_t *k = lv_label_create(parent);
+  lv_obj_t *label;
+
+  lv_obj_set_style_text_font(k, &lv_font_montserrat_16, 0);
+  lv_obj_set_style_text_color(k, lv_color_hex(LAUNCHER_TEXT_DIM), 0);
+  lv_label_set_text(k, key);
+  lv_obj_align(k, LV_ALIGN_TOP_LEFT, 60, y);
+
+  label = lv_label_create(parent);
+  lv_obj_set_style_text_font(label, &lv_font_montserrat_24, 0);
+  lv_obj_set_style_text_color(label, lv_color_hex(0xffffff), 0);
+  lv_label_set_text(label, val);
+  lv_obj_align(label, LV_ALIGN_TOP_LEFT, 60, y + 30);
+}
+
+static void launcher_create_about_scr(void)
+{
+  lv_obj_t *scr = lv_obj_create(NULL);
+  lv_obj_t *obj;
+
+  lv_obj_set_style_bg_color(scr, lv_color_hex(LAUNCHER_BG_COLOR), 0);
+
+  obj = lv_label_create(scr);
+  lv_obj_set_style_text_font(obj, &lv_font_montserrat_48, 0);
+  lv_obj_set_style_text_color(obj, lv_color_hex(0xffffff), 0);
+  lv_label_set_text(obj, "About this port");
+  lv_obj_align(obj, LV_ALIGN_TOP_MID, 0, 100);
+
+  launcher_about_info_line(scr, "BOARD", "VSAI LogicPi A1", 240);
+  launcher_about_info_line(scr, "SOC", "Amlogic S6 (ARM64)", 320);
+  launcher_about_info_line(scr, "INTERRUPT", "GICv3", 400);
+  launcher_about_info_line(scr, "DISPLAY", "MIPI DSI 1080x1920 RGB565",
+                           480);
+  launcher_about_info_line(scr, "TOUCH", "GT9XX I2C", 560);
+
+  g_about_heap = lv_label_create(scr);
+  lv_obj_set_style_text_font(g_about_heap, &lv_font_montserrat_24, 0);
+  lv_obj_set_style_text_color(g_about_heap, lv_color_hex(0xffffff), 0);
+  lv_label_set_text(g_about_heap, "heap: -");
+  lv_obj_align(g_about_heap, LV_ALIGN_TOP_LEFT, 60, 660);
+
+  g_about_fps = lv_label_create(scr);
+  lv_obj_set_style_text_font(g_about_fps, &lv_font_montserrat_24, 0);
+  lv_obj_set_style_text_color(g_about_fps, lv_color_hex(0xffffff), 0);
+  lv_label_set_text(g_about_fps, "fps: -");
+  lv_obj_align(g_about_fps, LV_ALIGN_TOP_LEFT, 60, 720);
+
+  obj = lv_button_create(scr);
+  lv_obj_set_size(obj, 440, 140);
+  lv_obj_set_style_radius(obj, 40, 0);
+  lv_obj_align(obj, LV_ALIGN_BOTTOM_MID, 0, -120);
+  lv_obj_add_event_cb(obj, launcher_back_event_cb, LV_EVENT_CLICKED, NULL);
+
+  {
+    lv_obj_t *lab = lv_label_create(obj);
+
+    lv_obj_set_style_text_font(lab, &lv_font_montserrat_24, 0);
+    lv_label_set_text(lab, LV_SYMBOL_LEFT " Back");
+    lv_obj_center(lab);
+  }
+
+  g_about_scr = scr;
+}
+
+/****************************************************************************
+ * Name: paint screen
+ ****************************************************************************/
+
+static void launcher_paint_dot(int32_t x, int32_t y, int32_t r)
+{
+  int32_t dx;
+  int32_t dy;
+  int32_t w = LAUNCHER_SCREEN_W;
+  int32_t h = LAUNCHER_SCREEN_H;
+
+  for (dy = -r; dy <= r; dy++)
+    {
+      for (dx = -r; dx <= r; dx++)
+        {
+          if (dx * dx + dy * dy <= r * r &&
+              x + dx >= 0 && x + dx < w && y + dy >= 0 && y + dy < h)
+            {
+              g_canvas_buf[(y + dy) * w + (x + dx)] = g_brush_color;
+            }
+        }
+    }
+}
+
+static void launcher_paint_stroke(int32_t x0, int32_t y0,
+                                  int32_t x1, int32_t y1)
+{
+  int32_t dx = x1 - x0;
+  int32_t dy = y1 - y0;
+  int32_t steps = abs(dx) > abs(dy) ? abs(dx) : abs(dy);
+  int32_t i;
+
+  if (steps == 0)
+    {
+      launcher_paint_dot(x1, y1, 6);
+      return;
+    }
+
+  for (i = 0; i <= steps; i += 4)
+    {
+      launcher_paint_dot(x0 + dx * i / steps, y0 + dy * i / steps, 6);
+    }
+}
+
+static void launcher_canvas_event_cb(lv_event_t *e)
+{
+  lv_event_code_t code = lv_event_get_code(e);
+  lv_indev_t *indev = lv_indev_active();
+  lv_point_t p;
+
+  if (indev == NULL)
+    {
+      return;
+    }
+
+  lv_indev_get_point(indev, &p);
+
+  if (code == LV_EVENT_PRESSED)
+    {
+      g_brush_down = true;
+      g_brush_prev = p;
+      launcher_paint_dot(p.x, p.y, 6);
+    }
+  else if (code == LV_EVENT_PRESSING && g_brush_down)
+    {
+      launcher_paint_stroke(g_brush_prev.x, g_brush_prev.y, p.x, p.y);
+      g_brush_prev = p;
+    }
+  else if (code == LV_EVENT_RELEASED)
+    {
+      g_brush_down = false;
+    }
+}
+
+static void launcher_paint_clear_cb(lv_event_t *e)
+{
+  UNUSED(e);
+  lv_canvas_fill_bg(g_canvas, lv_color_hex(0xffffff), LV_OPA_COVER);
+  lv_obj_invalidate(g_canvas);
+}
+
+static void launcher_paint_color_cb(lv_event_t *e)
+{
+  const lv_color_t *color = lv_event_get_user_data(e);
+
+  g_brush_color = *color;
+}
+
+static void launcher_paint_color_btn(lv_obj_t *parent, int idx)
+{
+  static lv_color_t button_colors[4];
+  lv_obj_t *btn = lv_button_create(parent);
+  lv_color_t c = lv_color_hex(g_palette[idx]);
+
+  button_colors[idx] = c;
+  lv_obj_set_size(btn, 70, 70);
+  lv_obj_set_style_radius(btn, LV_RADIUS_CIRCLE, 0);
+  lv_obj_set_style_bg_color(btn, c, 0);
+  lv_obj_align(btn, LV_ALIGN_TOP_LEFT, 280 + idx * 90, 25);
+  lv_obj_add_event_cb(btn, launcher_paint_color_cb, LV_EVENT_CLICKED,
+                      &button_colors[idx]);
+}
+
+static void launcher_create_paint_scr(void)
+{
+  lv_obj_t *scr = lv_obj_create(NULL);
+  lv_obj_t *obj;
+
+  lv_obj_set_style_bg_color(scr, lv_color_hex(0xffffff), 0);
+
+  g_canvas_buf = memalign(64, CANVAS_BUF_SIZE);
+  if (g_canvas_buf == NULL)
+    {
+      fprintf(stderr, "launcher: canvas alloc failed\n");
+      return;
+    }
+
+  g_canvas = lv_canvas_create(scr);
+  lv_canvas_set_buffer(g_canvas, g_canvas_buf, LAUNCHER_SCREEN_W,
+                       LAUNCHER_SCREEN_H, LV_COLOR_FORMAT_RGB565);
+  lv_canvas_fill_bg(g_canvas, lv_color_hex(0xffffff), LV_OPA_COVER);
+  lv_obj_add_flag(g_canvas, LV_OBJ_FLAG_CLICKABLE);
+  lv_obj_add_event_cb(g_canvas, launcher_canvas_event_cb, LV_EVENT_ALL,
+                      NULL);
+
+  obj = lv_obj_create(scr);
+  lv_obj_set_size(obj, LAUNCHER_SCREEN_W, 120);
+  lv_obj_set_style_bg_color(obj, lv_color_hex(LAUNCHER_CARD_COLOR), 0);
+  lv_obj_set_style_bg_opa(obj, LV_OPA_90, 0);
+  lv_obj_set_style_border_width(obj, 0, 0);
+  lv_obj_set_scrollbar_mode(obj, LV_SCROLLBAR_MODE_OFF);
+  lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
+  lv_obj_align(obj, LV_ALIGN_TOP_MID, 0, 0);
+
+  obj = lv_button_create(scr);
+  lv_obj_set_size(obj, 200, 70);
+  lv_obj_set_style_radius(obj, 24, 0);
+  lv_obj_align(obj, LV_ALIGN_TOP_LEFT, 40, 25);
+  lv_obj_add_event_cb(obj, launcher_back_event_cb, LV_EVENT_CLICKED, NULL);
+
+  {
+    lv_obj_t *lab = lv_label_create(obj);
+
+    lv_obj_set_style_text_font(lab, &lv_font_montserrat_16, 0);
+    lv_label_set_text(lab, LV_SYMBOL_LEFT " Back");
+    lv_obj_center(lab);
+  }
+
+  obj = lv_button_create(scr);
+  lv_obj_set_size(obj, 200, 70);
+  lv_obj_set_style_radius(obj, 24, 0);
+  lv_obj_align(obj, LV_ALIGN_TOP_RIGHT, -40, 25);
+  lv_obj_add_event_cb(obj, launcher_paint_clear_cb, LV_EVENT_CLICKED,
+                      NULL);
+
+  {
+    lv_obj_t *lab = lv_label_create(obj);
+
+    lv_obj_set_style_text_font(lab, &lv_font_montserrat_16, 0);
+    lv_label_set_text(lab, LV_SYMBOL_TRASH " Clear");
+    lv_obj_center(lab);
+  }
+
+  launcher_paint_color_btn(scr, 0);
+  launcher_paint_color_btn(scr, 1);
+  launcher_paint_color_btn(scr, 2);
+  launcher_paint_color_btn(scr, 3);
+
+  g_brush_color = lv_color_hex(g_palette[0]);
+  g_paint_scr = scr;
+}
