+/****************************************************************************
+ * Name: home screen
+ ****************************************************************************/
+
+static void launcher_home_btn_event_cb(lv_event_t *e)
+{
+  lv_obj_t *target = lv_event_get_user_data(e);
+
+  launcher_switch_scr(target, LV_SCR_LOAD_ANIM_MOVE_TOP);
+}
+
+static void launcher_home_btn(lv_obj_t *parent, const char *icon,
+                              const char *text, lv_obj_t *target,
+                              int32_t x)
+{
+  lv_obj_t *btn = lv_button_create(parent);
+
+  lv_obj_set_size(btn, 440, 300);
+  lv_obj_set_style_radius(btn, 48, 0);
+  lv_obj_set_style_bg_color(btn, lv_color_hex(LAUNCHER_CARD_COLOR), 0);
+  lv_obj_align(btn, LV_ALIGN_BOTTOM_MID, x, -180);
+  lv_obj_add_event_cb(btn, launcher_home_btn_event_cb, LV_EVENT_CLICKED,
+                      target);
+
+  {
+    lv_obj_t *lab = lv_label_create(btn);
+
+    lv_obj_set_style_text_font(lab, &lv_font_montserrat_48, 0);
+    lv_obj_set_style_text_color(lab, lv_color_hex(LAUNCHER_ACCENT), 0);
+    lv_label_set_text(lab, icon);
+    lv_obj_align(lab, LV_ALIGN_TOP_MID, 0, 50);
+
+    lab = lv_label_create(btn);
+    lv_obj_set_style_text_font(lab, &lv_font_montserrat_24, 0);
+    lv_obj_set_style_text_color(lab, lv_color_hex(0xffffff), 0);
+    lv_label_set_text(lab, text);
+    lv_obj_align(lab, LV_ALIGN_BOTTOM_MID, 0, -50);
+  }
+}
+
+static void launcher_create_home_scr(void)
+{
+  lv_obj_t *scr = lv_obj_create(NULL);
+  lv_obj_t *obj;
+
+  lv_obj_set_style_bg_color(scr, lv_color_hex(LAUNCHER_BG_COLOR), 0);
+
+  obj = lv_label_create(scr);
+  lv_obj_set_style_text_font(obj, &lv_font_montserrat_16, 0);
+  lv_obj_set_style_text_color(obj, lv_color_hex(LAUNCHER_TEXT_DIM), 0);
+  lv_label_set_text(obj, "FedoraVForce");
+  lv_obj_align(obj, LV_ALIGN_TOP_LEFT, 60, 60);
+
+  g_home_fps = lv_label_create(scr);
+  lv_obj_set_style_text_font(g_home_fps, &lv_font_montserrat_16, 0);
+  lv_obj_set_style_text_color(g_home_fps, lv_color_hex(LAUNCHER_TEXT_DIM),
+                              0);
+  lv_label_set_text(g_home_fps, "- fps");
+  lv_obj_align(g_home_fps, LV_ALIGN_TOP_RIGHT, -60, 60);
+
+  g_home_clock = lv_label_create(scr);
+  lv_obj_set_style_text_font(g_home_clock, &lv_font_montserrat_48, 0);
+  lv_obj_set_style_text_color(g_home_clock, lv_color_hex(0xffffff), 0);
+  lv_label_set_text(g_home_clock, "00:00:00");
+  lv_obj_align(g_home_clock, LV_ALIGN_CENTER, 0, -320);
+
+  g_home_uptime = lv_label_create(scr);
+  lv_obj_set_style_text_font(g_home_uptime, &lv_font_montserrat_24, 0);
+  lv_obj_set_style_text_color(g_home_uptime,
+                              lv_color_hex(LAUNCHER_TEXT_DIM), 0);
+  lv_label_set_text(g_home_uptime, "up -");
+  lv_obj_align(g_home_uptime, LV_ALIGN_CENTER, 0, -240);
+
+  obj = lv_label_create(scr);
+  lv_obj_set_style_text_font(obj, &lv_font_montserrat_24, 0);
+  lv_obj_set_style_text_color(obj, lv_color_hex(LAUNCHER_ACCENT), 0);
+  lv_label_set_text(obj, LV_SYMBOL_SETTINGS " NuttX / openvela");
+  lv_obj_align(obj, LV_ALIGN_CENTER, 0, 200);
+
+  launcher_home_btn(scr, LV_SYMBOL_LIST, "About", g_about_scr, -240);
+  launcher_home_btn(scr, LV_SYMBOL_EDIT, "Paint", g_paint_scr, 240);
+
+  g_home_scr = scr;
+}
+
+static void launcher_periodic_cb(lv_timer_t *timer)
+{
+  char buf[32];
+  struct mallinfo mi;
+
+  UNUSED(timer);
+
+  launcher_format_clock(buf, sizeof(buf));
+
+  if (lv_screen_active() == g_lock_scr && g_lock_clock != NULL)
+    {
+      lv_label_set_text(g_lock_clock, buf);
+    }
+  else if (lv_screen_active() == g_home_scr && g_home_clock != NULL)
+    {
+      mi = mallinfo();
+      lv_label_set_text(g_home_clock, buf);
+      lv_label_set_text_fmt(g_home_uptime, "up %us - heap %uKB free",
+                            launcher_uptime_sec(), mi.fordblks / 1024);
+    }
+
+  g_fps = g_refr_count;
+  g_refr_count = 0;
+
+  if (g_about_fps != NULL)
+    {
+      lv_label_set_text_fmt(g_about_fps, "fps: %u", g_fps);
+    }
+
+  if (g_about_heap != NULL)
+    {
+      mi = mallinfo();
+      lv_label_set_text_fmt(g_about_heap, "heap: %uKB free",
+                            mi.fordblks / 1024);
+    }
+
+  if (g_home_fps != NULL)
+    {
+      lv_label_set_text_fmt(g_home_fps, "%u fps", g_fps);
+    }
+}
+
+/****************************************************************************
+ * Public Functions
+ ****************************************************************************/
+
+int main(int argc, FAR char *argv[])
+{
+  lv_nuttx_dsc_t info;
+  lv_nuttx_result_t result;
+  char buf[32];
+
+  UNUSED(argc);
+  UNUSED(argv);
+
+  lv_init();
+
+  lv_nuttx_dsc_init(&info);
+  info.input_path = TOUCH_DEVPATH;
+  lv_nuttx_init(&info, &result);
+
+  if (result.disp == NULL)
+    {
+      fprintf(stderr, "launcher: no display found\n");
+      return 1;
+    }
+
+  if (result.indev == NULL)
+    {
+      fprintf(stderr, "launcher: no touchscreen found\n");
+      return 1;
+    }
+
+  lv_display_add_event_cb(result.disp, launcher_refr_event_cb,
+                          LV_EVENT_REFR_START, NULL);
+
+  launcher_create_about_scr();
+  launcher_create_paint_scr();
+  launcher_create_home_scr();
+  launcher_create_lock_scr();
+
+  lv_screen_load(g_lock_scr);
+
+  launcher_format_clock(buf, sizeof(buf));
+  lv_label_set_text(g_lock_clock, buf);
+
+  lv_timer_create(launcher_periodic_cb, 1000, NULL);
+
+  while (1)
+    {
+      uint32_t idle = lv_timer_handler();
+
+      idle = idle ? idle : 1;
+      usleep(idle * 1000);
+    }
+
+  return 0;
+}
